 k='10.1021/acsnano.8b07734';rid='B0016';si=L.ROOT/'assets/sources/acs-expansion-20261104/17371898-nn8b07734_si_001.pdf';main=L.ROOT/'assets/sources/pre2020-expansion/PMC6764109.xml';r=E.parse(main).getroot()
