 text=subprocess.check_output(['pdftotext','-layout',str(si),'-']).decode().split('References SI:',1)[1];refs=re.findall(r'(?ms)^\s*(\d+)\.\s*(.*?)(?=^\s*\d+\.\s|\Z)',text);assert len(refs)==3
